	private static void assertCloseAfterPendingBodyFailure(Throwable primary) throws Exception {
		IllegalStateException cleanup = new IllegalStateException("synthetic pending kernel source cleanup failure");
		Fixture fixture = new Fixture(primary, cleanup, CleanupSite.SOURCE, Schedule.BODY_FIRST);
		RowCursor cursor = fixture.open();
		Throwable initiatingFailure = null;
		try {
			assertThat(cursor.next()).as("a real first page must escape before the body failure is enabled").isTrue();
			fixture.releaseFailure.countDown();
			assertThat(fixture.failedProbeClosed.await(10L, TimeUnit.SECONDS))
					.as("the failing worker probe must close before the owner closes the cursor")
					.isTrue();
			assertThat(catchThrowable(cursor::close)).as("public close reports the distinct cleanup failure")
					.isSameAs(cleanup);
			assertThat(catchThrowable(cursor::close)).as("the terminal cursor close is reported once").isNull();
		} catch (Exception | Error failure) {
			initiatingFailure = failure;
			throw failure;
		} finally {
			fixture.releaseFailure.countDown();
			try {
				cursor.close();
			} catch (RuntimeException | Error closing) {
				if (initiatingFailure == null) {
					throw closing;
				}
				if (closing != initiatingFailure) {
					initiatingFailure.addSuppressed(closing);
				}
			}
		}
		fixture.assertReleased();
		assertThat(fixture.children.get(0).failureCalls).hasValue(1);
		assertThat(fixture.children.get(1).cleanupCalls).hasValue(1);
		assertThat(KernelCancelledException.INSTANCE.getSuppressed()).isEmpty();
	}

