	private static NativeLmdbQuerySource.NativeAdjacency adjacencyWithClose(Throwable closeFailure,
			AtomicInteger closeCalls) {
		return new NativeLmdbQuerySource.NativeAdjacency() {
			@Override
			public long find(long key) {
				return NativeLmdbQuerySource.NativeAdjacency.NOT_FOUND;
			}

			@Override
			public long size(long runHandle) {
				return 0L;
			}

			@Override
			public long neighborAt(long runHandle, long runOffset) {
				throw new AssertionError("a close-only adjacency must not be read");
			}

			@Override
			public long contextAt(long runHandle, long runOffset) {
				throw new AssertionError("a close-only adjacency must not be read");
			}

			@Override
			public void close() {
				closeCalls.incrementAndGet();
				if (closeFailure instanceof RuntimeException runtime) {
					throw runtime;
				}
				if (closeFailure instanceof Error error) {
					throw error;
				}
			}
		};
	}

	private static void assertAdjacenciesReleased(NativeLmdbQuerySource.NativeAdjacency[] views,
			AtomicInteger[] closeCalls) {
		for (NativeLmdbQuerySource.NativeAdjacency view : views) {
			assertThat(view).isNull();
		}
		for (AtomicInteger closeCall : closeCalls) {
			assertThat(closeCall).hasValue(1);
		}
		assertThat(LmdbNativeKernelBindings.closeAdjacencies(views, null))
				.as("releasing an already released view array is quiet")
				.isNull();
		for (AtomicInteger closeCall : closeCalls) {
			assertThat(closeCall).hasValue(1);
		}
	}

	private static Throwable assertCleanupBeforeBody(Throwable primary) throws Exception {
		RuntimeException cleanup = new IllegalStateException("synthetic earlier kernel cleanup failure");
		Fixture fixture = new Fixture(primary, cleanup, CleanupSite.SOURCE, Schedule.CLEANUP_FIRST);
		ExecutorService consumer = Executors.newSingleThreadExecutor();
		RowCursor cursor = null;
		Future<Throwable> outcome = null;
		Throwable observed;
		try (var registration = QueryExecutionContext.activateReplaySafepoint(() -> {
		}, () -> () -> () -> {
			if (fixture.children.size() == 2 && fixture.children.get(1).workerThread == Thread.currentThread()
					&& fixture.children.get(1).cleanupCalls.get() == 1) {
				// WorkerTasks closes the captured scope AFTER native cleanup publishes its failure destination.
				fixture.cleanupPublished.countDown();
			}
		})) {
			cursor = fixture.open();
			assertThat(cursor.next()).isTrue();
			RowCursor selected = cursor;
			outcome = consumer.submit(() -> catchThrowable(() -> {
				while (selected.next()) {
					assertThat(fixture.row.slots[0]).isBetween(1L, (long) ROOTS);
				}
			}));
			assertThat(fixture.primaryEntered.await(10L, TimeUnit.SECONDS))
					.as("the real body probe must already be in flight before earlier cleanup settles")
					.isTrue();
			assertThat(fixture.cleanupPublished.await(10L, TimeUnit.SECONDS))
					.as("the distinct cleanup destination is published before the body is released")
					.isTrue();
			fixture.releaseFailure.countDown();
			observed = outcome.get(10L, TimeUnit.SECONDS);
			assertThat(observed).isNotNull();
			assertThat(observed.getSuppressed()).contains(cleanup);
			int copies = 0;
			for (Throwable suppressed : observed.getSuppressed()) {
				if (suppressed == cleanup) {
					copies++;
				}
			}
			assertThat(copies).as("the distinct cleanup is retained exactly once on the final body failure").isOne();
			assertThat(catchThrowable(selected::close)).isNull();
		} finally {
			fixture.releaseFailure.countDown();
			if (outcome != null && !outcome.isDone()) {
				outcome.cancel(true);
			}
			consumer.shutdownNow();
			try (RowCursor owned = cursor) {
				assertThat(consumer.awaitTermination(10L, TimeUnit.SECONDS)).isTrue();
			}
		}
		fixture.assertReleased();
		assertThat(fixture.children.get(0).failureCalls).hasValue(1);
		assertThat(fixture.children.get(1).cleanupCalls).hasValue(1);
		return observed;
	}

